/* CCNA Gym Cards — Domain 3 IP Connectivity (25%) — decks rtable, static, ospf, fhrp */
export const CCNA_CARDS_D3 = [
 /* ---------- rtable (26) — 3.1 routing table components, 3.2 forwarding decision ---------- */
 {obj:"3.1.a",c:"rtable",q:"Route code C",a:"#Connected network\nThe subnet of an interface that is up/up with an IPv4 address",s:"Subnet attached to an up/up interface",
  x:"A C route appears automatically for the subnet of every interface that has an address and is up/up; no protocol or command is needed beyond configuring the address and 'no shutdown'. Connected routes have an administrative distance of 0, so nothing overrides them. If the interface goes down, the C route (and its L partner) disappears from the table, which is a fast way to spot a down link in show ip route.",
  w:"C = I am physically on this subnet."},
 {obj:"3.1.a",c:"rtable",q:"Route code L",a:"#Local route — the router's own interface address\nAlways a /32 (IPv4) or /128 (IPv6) host route",s:"/32 host route for the router's own interface IP",
  x:"IOS 15 and later add an L route for each interface address, for example 'L 10.0.12.1/32 is directly connected, GigabitEthernet0/0'. It tells the router that packets addressed to that exact IP are for the router itself and must be handed to the control plane, not forwarded. Every C route has a matching L route. In IPv6 tables the local route is a /128. Exam trap: the L route is not a separate subnet and is never advertised by OSPF.",
  w:"Each C has an L twin: the subnet, then the router's own /32."},
 {obj:"3.1.a",c:"rtable",q:"Route code S vs S*",a:"#S = static route; S* = static candidate default\nThe asterisk marks a route that can become the gateway of last resort",s:"Static route; asterisk marks a candidate default",
  x:"An S entry was entered by hand with ip route (or ipv6 route). The asterisk is not a separate protocol: it marks a candidate default, normally 0.0.0.0/0, so 'S* 0.0.0.0/0 [1/0] via 203.0.113.1' is a static default route. The same asterisk shows up on dynamically learned defaults such as O*E2. When an S* is installed, the header line 'Gateway of last resort is …' names its next hop.",
  w:"The star means 'candidate default', whatever letter it sits on."},
 {obj:"3.1.a",c:"rtable",q:"Route code O",a:"#OSPF intra-area route\nLearned from router and network LSAs in the router's own area",s:"OSPF route from the router's own area",
  x:"A plain O route was learned through OSPF from inside the same area, built from type 1 (router) and type 2 (network) LSAs. In the single-area designs CCNA tests, every OSPF-learned subnet is a plain O. The bracket shows [110/cost]: 110 is OSPF's administrative distance and the second number is the cumulative cost to reach the prefix. Compare O IA (another area) and O E2 (redistributed from outside OSPF).",
  w:"O alone = same area."},
 {obj:"3.1.a",c:"rtable",q:"Route code O IA",a:"#OSPF inter-area route\nA prefix from another area, advertised by an ABR as a type 3 summary LSA",s:"OSPF route learned from a different area",
  x:"O IA means the destination lives in a different OSPF area and reached this router through an area border router, which advertises it as a type 3 summary LSA. CCNA configuration is single-area, so you mostly need to recognise the code when reading a table. AD is still 110; the metric is the cost to the ABR plus the ABR's advertised cost to the prefix. Intra-area O routes are preferred over O IA for the same prefix.",
  w:"IA = Inter-Area, via an ABR."},
 {obj:"3.1.a",c:"rtable",q:"Route code O*E2",a:"#OSPF external type 2 default route\nTypically produced by default-information originate on another router",s:"OSPF-learned external default route",
  x:"E2 marks a route that entered OSPF from outside, such as a static route redistributed by an ASBR, and the asterisk marks it as a candidate default. 'O*E2 0.0.0.0/0 [110/1] via 10.0.12.1' is what neighbors see after a router runs default-information originate. Type 2 external metrics stay at the seed value (1 for a default) across the domain instead of adding internal cost, so every router shows the same metric for it.",
  w:"O*E2 0.0.0.0/0 = someone ran default-information originate."},
 {obj:"3.1.a",c:"rtable",q:"Route code D",a:"#EIGRP route\nAD 90 internal; D EX = external EIGRP, AD 170",s:"EIGRP-learned route",
  x:"D is the code for EIGRP routes, with administrative distance 90 for internal routes. Routes redistributed into EIGRP show as D EX with AD 170. The metric in the bracket is a large composite number calculated by default from the slowest bandwidth and the total delay along the path. CCNA v1.1 no longer has you configure EIGRP, but you must read D routes and know that AD 90 beats OSPF's 110.",
  w:"D = EIGRP, 90 beats OSPF's 110."},
 {obj:"3.1.a",c:"rtable",q:"Route code R",a:"#RIP route\nAD 120; metric = hop count, 16 means unreachable",s:"RIP route measured in hops",
  x:"R marks a route learned from RIP, a distance-vector protocol whose metric is simply the number of routers to cross; 15 is the maximum usable value and 16 means unreachable. Its administrative distance of 120 is higher than OSPF (110) and EIGRP (90), so if the same prefix is learned from both RIP and OSPF, the OSPF route is installed. Example line: 'R 172.16.4.0/24 [120/2] via 10.0.23.3'.",
  w:"R = RIP: [120/hops]."},
 {obj:"3.1.a",c:"rtable",q:"Route code B",a:"#BGP route\neBGP AD 20, iBGP AD 200",s:"BGP-learned route",
  x:"B identifies a route learned from BGP, the protocol used between autonomous systems such as an enterprise and its ISP. The administrative distance depends on the session: routes from an external peer (eBGP) get 20, more trusted than any IGP, while routes from an internal peer (iBGP) get 200. At CCNA level you need to recognise the code and its two AD values rather than configure BGP.",
  w:"B: external 20, internal 200."},
 {obj:"3.1",c:"rtable",q:"Read it: O 10.1.3.0/24 [110/2] via 10.0.12.2, 00:12:34, Gi0/0",a:"#Code, prefix/mask, [AD/metric], next hop, age, exit interface\nOSPF · 10.1.3.0/24 · AD 110, cost 2 · via 10.0.12.2 · learned 12m34s ago · out Gi0/0",s:"Code, prefix, [AD/metric], next hop, age, interface",
  x:"Read a route line left to right: the source code (O = OSPF), the destination prefix with its mask length, then [administrative distance/metric] in brackets, then 'via' and the next-hop IP, then how long the route has been in the table, and finally the outgoing interface. Exam items often point at one field and ask what it is; the most common trap is swapping the two numbers in the bracket. AD always comes first.",
  w:"[first/second] = [AD/metric], never the reverse."},
 {obj:"3.1.b",c:"rtable",q:"Prefix and mask in the routing table",a:"#Destination network plus its prefix length\n'10.0.0.0/8 is variably subnetted, 5 subnets, 2 masks' groups them",s:"Destination network and prefix length",
  x:"Each entry names a destination prefix (10.1.3.0) and its mask, written as a prefix length (/24). IOS groups subnets of the same classful network under a parent line such as '10.0.0.0/8 is variably subnetted, 5 subnets, 2 masks'; that parent line is a heading, not a route you can forward on. The mask length matters because forwarding uses the most specific matching prefix, so 10.1.3.0/24 and 10.1.3.0/25 are different routes.",
  w:"Prefix + length = one route; the 'is subnetted' line is just a header."},
 {obj:"3.1.c",c:"rtable",q:"Same network, different masks",a:"#10.1.0.0/16 and 10.1.0.0/24 are separate routes\nBoth can be installed; the mask makes them distinct",s:"Different mask length means a different route",
  x:"The routing table keys each entry on prefix and mask together. 10.1.0.0/16 and 10.1.0.0/24 do not compete with each other, even if they come from different protocols, because they describe different ranges; both are installed and the longest match decides per packet. Only routes with the identical prefix and identical mask are compared on administrative distance and metric. Misreading a mask is a classic cause of 'wrong route' answers.",
  w:"Same prefix + same mask competes; different mask coexists."},
 {obj:"3.1.d",c:"rtable",q:"Next hop and exit interface in a route",a:"#'via 10.0.12.2' = next-hop router; 'Gi0/0' = outgoing interface\nThe next hop must be on a connected subnet to be used",s:"Neighbor IP to forward to, and interface to use",
  x:"The next hop is the IP address of the neighboring router that receives the packet; the router ARPs for that address, not for the final destination. The exit interface at the end of the line is where the frame leaves. A route showing only 'is directly connected, Gi0/0' has no next-hop IP, which is normal for C and L routes and for a static route defined with only an exit interface. The age field (00:12:34) only shows how long the route has been present.",
  w:"Router ARPs for the next hop, never for the far destination."},
 {obj:"3.1.e",c:"rtable",q:"Administrative distance — what it is",a:"#Trustworthiness of a route source; lower wins\nCompared only when two sources offer the same prefix and mask",s:"Believability of the route source, lower preferred",
  x:"Administrative distance ranks route sources (connected, static, OSPF, EIGRP and so on) so a router can choose when two sources offer the exact same prefix and mask. Lower is better, from 0 for connected to 255, which means 'never install'. It is locally significant: it is not carried in updates, and you can change it on one router, which is exactly how a floating static route works. It is the first number inside the brackets.",
  w:"AD picks between sources; metric picks between paths of one source."},
 {obj:"3.1.e",c:"rtable",q:"AD: connected and static",a:"#Connected 0, static 1\nA static route via next hop shows as [1/0]",s:"Connected 0, static 1",
  x:"Connected routes have AD 0 and static routes default to AD 1, so a hand-entered static route beats any dynamic protocol for the same prefix unless you raise its AD. A static route with a next hop appears as 'S 10.5.0.0/16 [1/0] via 10.0.12.2'; static routes have no real metric, hence the 0. You can append a distance to the ip route command, such as 130, to make the static a backup that loses to OSPF.",
  w:"0 connected, 1 static — both beat every routing protocol."},
 {obj:"3.1.e",c:"rtable",q:"AD: eBGP, EIGRP, OSPF, RIP",a:"#eBGP 20 · EIGRP 90 · OSPF 110 · RIP 120\nLower number is preferred for the same prefix",s:"eBGP 20, EIGRP 90, OSPF 110, RIP 120",
  x:"The common dynamic AD values in ascending order are external BGP 20, internal EIGRP 90, OSPF 110, IS-IS 115 and RIP 120. If R1 learns 10.9.9.0/24 through both EIGRP and OSPF, it installs the EIGRP route regardless of metrics, because metrics from different protocols are not comparable. Memorise these as a ladder; many exam items show two candidate routes and ask which one ends up in the table.",
  w:"20 – 90 – 110 – 115 – 120: climb the ladder, trust falls."},
 {obj:"3.1.e",c:"rtable",q:"AD: EIGRP external, iBGP, 255",a:"#EIGRP external 170 · iBGP 200 · 255 = unusable\nA route with AD 255 is never installed",s:"EIGRP external 170, iBGP 200, 255 never used",
  x:"Routes redistributed into EIGRP (D EX) carry AD 170, and routes from internal BGP peers carry 200, both deliberately less trusted than any IGP. AD 255 marks a source as untrusted: a route with that distance is never placed in the routing table. Knowing the high end matters for floating static design, because the backup's AD must be above the primary source's value but below 255.",
  w:"255 = the router will not believe it."},
 {obj:"3.1.f",c:"rtable",q:"Metric — what it is, per protocol",a:"#Cost of a path within one protocol; lower wins\nOSPF cost · RIP hop count · EIGRP composite (bandwidth + delay)",s:"Path cost within one protocol, lower preferred",
  x:"The metric is the second number in the brackets and is how a single routing protocol chooses between its own paths to a prefix. Each protocol measures differently: OSPF adds interface costs derived from bandwidth, RIP counts hops, EIGRP by default combines the slowest bandwidth and total delay. Because the units differ, a router never compares an OSPF metric with a RIP metric; administrative distance settles that first.",
  w:"Metric compares paths inside one protocol only."},
 {obj:"3.1.f",c:"rtable",q:"Metric of connected and static routes",a:"#0\nConnected routes show no bracket; static via next hop shows [1/0]",s:"Zero for static and connected routes",
  x:"Static routes have a metric of 0, so a static via a next hop reads [1/0], or [130/0] for a floating static with AD 130. Connected and local routes are printed as 'is directly connected' with no bracket at all. If an item shows two static routes for the same prefix with the same AD, they tie and both are installed for load sharing, because there is no metric to break the tie.",
  w:"Static: [AD/0]."},
 {obj:"3.1.g",c:"rtable",q:"Gateway of last resort",a:"#The next hop of the installed default route\n'Gateway of last resort is not set' = unknown destinations are dropped",s:"Next hop used when no other route matches",
  x:"The gateway of last resort line at the top of show ip route names where the router sends packets that match nothing more specific, for example 'Gateway of last resort is 203.0.113.1 to network 0.0.0.0'. It is filled in when a default route (0.0.0.0/0) is installed, whether static (S*) or learned (O*E2, D*EX and so on). If it reads 'not set', packets to unknown destinations are dropped and the sender may get an ICMP unreachable.",
  w:"No default route = 'not set' = unknown traffic is dropped."},
 {obj:"3.1.g",c:"rtable",q:"Two ways a GOLR gets set (CCNA scope)",a:"#Static default route, or a default learned from a routing protocol\nip route 0.0.0.0 0.0.0.0 … or OSPF default-information originate",s:"Static default or a dynamically learned default",
  x:"On an edge router you normally configure a static default, ip route 0.0.0.0 0.0.0.0 next-hop, which appears as S* and sets the gateway of last resort. Inside an OSPF domain the edge router then runs default-information originate so every other router learns O*E2 0.0.0.0/0 and sets its own gateway of last resort to its OSPF neighbor. Each router's GOLR is its own next hop, not necessarily the ISP's address.",
  w:"Edge: static S*. Interior: learned O*E2."},
 {obj:"3.2.a",c:"rtable",q:"Longest prefix match",a:"#The most specific matching route wins, first\nChecked before AD and metric are considered",s:"Most specific matching route is chosen first",
  x:"For every packet the router finds all routes whose prefix contains the destination and uses the one with the longest mask. For 10.1.1.5 with routes 0.0.0.0/0, 10.1.0.0/16 and 10.1.1.0/24 installed, the /24 wins. AD and metric never enter this per-packet choice; they were used earlier, when deciding which route for an identical prefix and mask got installed. The default route, /0, always matches and always loses to anything more specific.",
  w:"Longest mask wins, every packet."},
 {obj:"3.2.a",c:"rtable",q:"RIP /25 vs OSPF /24 — which forwards 10.4.4.10?",a:"#The RIP /25, if it contains the address\nDifferent masks are both installed; longest match beats lower AD",s:"The /25 route, despite the worse AD",
  x:"10.4.4.0/25 from RIP (AD 120) and 10.4.4.0/24 from OSPF (AD 110) are different prefixes, so both are installed. A packet to 10.4.4.10 falls inside the /25 and is forwarded on the RIP route, while 10.4.4.200 only matches the /24 and uses OSPF. This is the most common forwarding-decision trap: AD only breaks ties between routes for exactly the same prefix and mask, never between a /24 and a /25.",
  w:"AD never overrides a longer match."},
 {obj:"3.2.b",c:"rtable",q:"Same prefix from OSPF and EIGRP",a:"#Install the EIGRP route (AD 90 beats 110)\nThe OSPF route stays in the OSPF database as a backup",s:"The EIGRP route (AD 90) is installed",
  x:"When two sources offer the identical prefix and mask, the router installs the one with the lower administrative distance; metrics are not compared because they are in different units. EIGRP (90) therefore beats OSPF (110) for 172.16.8.0/24. The losing route is not lost: if the EIGRP route disappears, the OSPF route is installed from the OSPF database. Raising a static route's AD above 110 uses this same rule to build a backup.",
  w:"Same prefix, different sources: lowest AD."},
 {obj:"3.2.c",c:"rtable",q:"Two OSPF paths, cost 20 and cost 30",a:"#Install the cost 20 path only\nSame source, so metric decides",s:"Only the cost-20 path is installed",
  x:"When one routing protocol has several paths to the same prefix and mask, it offers the lowest-metric path to the routing table. OSPF with paths costing 20 and 30 installs only the cost 20 path; the other stays in the topology as a fallback. The full decision order is: longest prefix match per packet, and for an identical prefix the lowest AD across sources, then the lowest metric within the winning source.",
  w:"Prefix length, then AD, then metric."},
 {obj:"3.2",c:"rtable",q:"Equal-cost multipath (ECMP)",a:"#Equal-metric paths are all installed and shared\nOSPF installs up to 4 by default (maximum-paths)",s:"Equal paths installed together for load sharing",
  x:"If a protocol finds two or more paths with the identical lowest metric, it installs all of them, up to its maximum-paths setting (4 by default for OSPF on IOS). The table then lists one prefix with multiple 'via' lines, for example two [110/3] entries out Gi0/0 and Gi0/1. Cisco Express Forwarding shares traffic across them, per destination by default. Unequal-cost load balancing is not done by OSPF.",
  w:"Two 'via' lines under one prefix = ECMP."},

 /* ---------- static (22) — 3.3 IPv4 and IPv6 static routing ---------- */
 {obj:"3.3",c:"static",q:"IPv4 static route syntax",a:"#ip route prefix mask {next-hop | exit-if [next-hop]} [AD]\nip route 10.5.0.0 255.255.0.0 10.0.12.2",s:"ip route prefix mask next-hop-or-interface [AD]",
  x:"The global command ip route takes the destination network, a dotted-decimal mask (not a prefix length), and then a next-hop address, an exit interface, or both. An optional number at the end sets the administrative distance, default 1. The prefix must be the network address itself; IOS will reject or correct a host-bit mistake such as 10.5.1.0 with a /16 mask ('Inconsistent address and mask').",
  w:"Dotted mask, not /16, in ip route."},
 {obj:"3.3.b",c:"static",q:"Static route with a next-hop IP",a:"#ip route 10.5.0.0 255.255.0.0 10.0.12.2\nShown as S … [1/0] via 10.0.12.2; needs a recursive lookup",s:"Points at a neighbor's IP address",
  x:"Giving only a next-hop address is the most common form. The router must then look up 10.0.12.2 in its own table to find which connected interface reaches it, a recursive lookup. The route appears as 'S 10.5.0.0/16 [1/0] via 10.0.12.2'. If the next hop stops being reachable (for example, the connected subnet goes down), the static route is withdrawn from the table automatically.",
  w:"Next-hop only = recursive lookup."},
 {obj:"3.3.b",c:"static",q:"Static route with only an exit interface",a:"#ip route 10.5.0.0 255.255.0.0 Serial0/0/0\nShown as 'is directly connected'; fine on point-to-point links",s:"Names only the outgoing interface",
  x:"Naming only the exit interface makes the router treat the destination as if it were directly connected, so the table shows 'S 10.5.0.0/16 is directly connected, Serial0/0/0' with AD still 1. On a point-to-point serial link that is fine because there is only one possible receiver. On Ethernet it is a poor choice: the router ARPs for every destination address and relies on the neighbor answering with proxy ARP.",
  w:"Exit-interface-only on Ethernet leans on proxy ARP."},
 {obj:"3.3.b",c:"static",q:"Fully specified static route",a:"#ip route 10.5.0.0 255.255.0.0 g0/0 10.0.12.2\nExit interface AND next hop — no recursion, no proxy ARP",s:"Exit interface plus next-hop address",
  x:"A fully specified static route gives both the outgoing interface and the next-hop address. The router knows where to send the frame without a recursive lookup and ARPs only for the next hop, so it avoids the proxy-ARP dependence of an interface-only route on Ethernet. The route is withdrawn if that interface goes down. In IPv6 this form is mandatory whenever the next hop is a link-local address.",
  w:"Interface + next hop = fully specified."},
 {obj:"3.3",c:"static",q:"Recursive route lookup",a:"#Look up the destination, then look up the next hop\nThe second lookup finds the exit interface",s:"Second table lookup to resolve the next hop",
  x:"When a static route names only a next-hop IP, forwarding needs two lookups: the destination matches the static route, then the next hop itself is looked up to find the connected route and exit interface. Modern IOS precomputes this in CEF, but the dependency still matters: if no route covers the next hop, the static route is not installed. A static route that points at a next hop learned only through another static route can chain lookups further.",
  w:"Next hop must itself be routable."},
 {obj:"3.3.a",c:"static",q:"IPv4 static default route",a:"#ip route 0.0.0.0 0.0.0.0 203.0.113.1\nMatches every destination; appears as S* 0.0.0.0/0",s:"ip route 0.0.0.0 0.0.0.0 next-hop",
  x:"A default route uses all-zero prefix and mask, so it matches any address but, as a /0, loses to every more specific route. It is typical on a branch or edge router with a single path to the ISP. Once installed it is shown as 'S* 0.0.0.0/0 [1/0] via 203.0.113.1' and the header line becomes 'Gateway of last resort is 203.0.113.1 to network 0.0.0.0'. An exit interface or fully specified form also works.",
  w:"0.0.0.0 0.0.0.0 = quad zero, matches everything last."},
 {obj:"3.3.a",c:"static",q:"Where a default route is the right tool",a:"#Stub site with one way out\nA branch router whose only exit is the WAN or the ISP",s:"Stub network with a single exit path",
  x:"A stub network has only one path to everything else, so listing every remote prefix is pointless; one default route covers all of them. The upstream router still needs specific routes (static or dynamic) back to the stub's subnets, otherwise replies have no return path. Edge routers often combine a static default toward the ISP with OSPF default-information originate so internal routers learn the exit automatically.",
  w:"Stub = default out, specific routes back in."},
 {obj:"3.3.b",c:"static",q:"Static network route",a:"#Points to a whole remote subnet\nip route 192.168.30.0 255.255.255.0 10.0.23.3",s:"Static route to an entire remote subnet",
  x:"A network route covers one remote subnet, like 192.168.30.0/24 behind R3, and is the everyday use of static routing. It must use the network address and the matching mask. It appears as 'S 192.168.30.0/24 [1/0] via 10.0.23.3'. Network routes fall between a host route (/32, most specific) and a default route (/0, least specific), and longest-prefix match decides which is used for a given packet.",
  w:"Network route = one subnet, network address + its mask."},
 {obj:"3.3.c",c:"static",q:"Static host route",a:"#ip route 192.168.30.10 255.255.255.255 10.0.13.3\nA /32 to one single address",s:"/32 route to exactly one IPv4 address",
  x:"A host route uses mask 255.255.255.255 (/32) and so matches exactly one destination. Because it is the longest possible prefix it overrides any network or default route for that address, which makes it useful for steering traffic to one server over a different path, such as a dedicated link to a management host. In IPv6 the equivalent is a /128. Do not confuse it with the L local route, which is the router's own address.",
  w:"Host route = /32 (or /128) — always the most specific."},
 {obj:"3.3.d",c:"static",q:"Floating static route",a:"#Backup static with an AD higher than the primary\nStays out of the table until the primary route disappears",s:"Backup static whose AD exceeds the primary's",
  x:"A floating static route is a normal static route whose administrative distance has been raised above that of the primary route for the same prefix. While the primary (an OSPF route at 110, say) exists, the static loses and is not installed. If the primary is withdrawn, the floating static 'floats' into the table. When the primary returns, it displaces the static again. The prefix and mask must be identical for AD to be compared.",
  w:"Floating = hidden by a lower AD until needed."},
 {obj:"3.3.d",c:"static",q:"Floating default as a backup to OSPF",a:"#ip route 0.0.0.0 0.0.0.0 198.51.100.1 130\n130 is above OSPF's 110, so OSPF wins while it is up",s:"ip route 0.0.0.0 0.0.0.0 next-hop 130",
  x:"Adding a distance to the end of ip route turns it into a floating static. With OSPF providing the primary default at AD 110, a static default at 130 stays out of the table and is only installed if the OSPF default vanishes. Any value from 111 to 254 would work here; 130 is just a common choice. Verify with show ip route: while OSPF is up you see O*E2 0.0.0.0/0, and after failover you see S* 0.0.0.0/0 [130/0].",
  w:"AD at the end of the line: 130 > 110."},
 {obj:"3.3.d",c:"static",q:"Floating static with AD 5 vs OSPF",a:"#Not floating — it replaces the OSPF route\nAD 5 is lower than 110, so the static is always installed",s:"AD below the primary makes it the primary",
  x:"A floating static only works when its AD is higher than the primary route's AD. A static route with distance 5 still beats OSPF (110), EIGRP (90) and RIP (120), so it becomes the active route and the dynamic route becomes the unused one. To back up EIGRP the static needs more than 90; to back up OSPF, more than 110. Exam items like to show 'ip route … 100' as a supposed OSPF backup, which actually overrides OSPF.",
  w:"Backup AD must be HIGHER than the primary's."},
 {obj:"3.3",c:"static",q:"When does a static route leave the table?",a:"#When its exit interface goes down or its next hop is unresolvable\nIt returns automatically when the condition clears",s:"Exit interface down or next hop unreachable",
  x:"IOS keeps a static route in the routing table only while it is usable: the exit interface (if named) must be up/up and the next hop (if named) must be resolvable through another route. If the connected link fails, the route is removed, which is what lets a floating static take over. A static route cannot detect a failure beyond the directly connected link, such as an ISP problem two hops away, without extra features like IP SLA tracking.",
  w:"Static routes only notice local link failures."},
 {obj:"3.3",c:"static",q:"Static routing needs a return path",a:"#Add routes on both ends\nR1 needs a route to R3's LAN, and R3 needs one back to R1's LAN",s:"Routes must exist in both directions",
  x:"Routing is hop by hop and one way. If only R1 has a route to 192.168.30.0/24, pings from R1's LAN reach R3's LAN but the replies are dropped because R3 has no route back to 192.168.10.0/24 (or no default). Troubleshooting a one-way static setup is a frequent lab and exam theme: check each router along the path, in both directions, for a matching route or default.",
  w:"Ping fails? Check the way back."},
 {obj:"3.3",c:"static",q:"ipv6 unicast-routing",a:"#ipv6 unicast-routing\nGlobal command that lets the router forward IPv6 packets",s:"Enables IPv6 packet forwarding on the router",
  x:"By default an IOS router acts as an IPv6 host: interfaces can have IPv6 addresses, but the router will not forward IPv6 packets between them, will not send router advertisements, and cannot run OSPFv3. The global command ipv6 unicast-routing turns on IPv6 routing. Forgetting it is a classic lab mistake when static IPv6 routes look correct in the configuration but traffic still does not pass through the router.",
  w:"No ipv6 unicast-routing = no IPv6 forwarding."},
 {obj:"3.3.a",c:"static",q:"IPv6 static default route",a:"#ipv6 route ::/0 2001:db8:0:12::2\nShown as S ::/0 in show ipv6 route",s:"ipv6 route ::/0 next-hop",
  x:"The IPv6 default route is ::/0, the IPv6 counterpart of 0.0.0.0/0. Unlike ip route, ipv6 route takes the prefix in slash notation rather than a separate mask. The next hop can be a global unicast address, an exit interface (on point-to-point links), or an interface plus link-local address. As with IPv4 it can be made floating by adding a distance, for example 'ipv6 route ::/0 2001:db8:0:99::1 130'.",
  w:"IPv6 default = ::/0, slash notation."},
 {obj:"3.3.b",c:"static",q:"IPv6 static network route",a:"#ipv6 route 2001:db8:0:30::/64 2001:db8:0:23::3\nPrefix in slash notation, then next hop",s:"ipv6 route prefix/len next-hop",
  x:"An IPv6 network route names the remote /64 (or other length) directly in prefix/length form and then the next hop. The next hop here is a global unicast address on the shared link, so no exit interface is needed and the router performs a recursive lookup just as in IPv4. In show ipv6 route the entry reads 'S 2001:DB8:0:30::/64 [1/0] via 2001:DB8:0:23::3'. AD is 1 unless you specify otherwise.",
  w:"ipv6 route uses /len, not a mask."},
 {obj:"3.3",c:"static",q:"IPv6 static with a link-local next hop",a:"#Must also name the exit interface\nipv6 route 2001:db8:0:30::/64 g0/0 fe80::3",s:"Link-local next hop requires the exit interface",
  x:"Link-local addresses (fe80::/10) are only unique per link, and every interface on a router can carry the same one, so a link-local next hop alone is ambiguous. IOS refuses the command unless an outgoing interface is named before the link-local address. Using link-local next hops is common because they do not change if global addressing is renumbered, and they match how IPv6 routing protocols advertise next hops.",
  w:"fe80:: next hop? Name the interface."},
 {obj:"3.3.c",c:"static",q:"IPv6 host route",a:"#A /128 static route\nipv6 route 2001:db8:0:30::10/128 2001:db8:0:23::3",s:"/128 route to exactly one IPv6 address",
  x:"The IPv6 host route uses a /128 prefix and matches one address only, overriding any /64 network route or ::/0 default through longest-prefix match. IOS also builds /128 entries automatically as L (local) routes for each of its own interface addresses, so in show ipv6 route you will see /128 lines even without any static host routes configured. Telling those apart from a configured S /128 is about the code letter.",
  w:"/128 = IPv6 host route; L /128 = the router itself."},
 {obj:"3.3.d",c:"static",q:"IPv6 floating static route — how is the distance set?",a:"#ipv6 route ::/0 2001:db8:0:99::1 130\nDistance at the end, same as IPv4",s:"A distance at the end of ipv6 route, as in IPv4",
  x:"IPv6 static routes accept an administrative distance at the end of the command just like IPv4. With OSPFv3 or a primary static providing the normal path, a backup ::/0 at distance 130 stays out of the IPv6 table until the primary is removed. The same rule applies: the floating route's distance must be higher than that of the route it backs up, and the prefix length must match exactly.",
  w:"Same floating rule in IPv6: higher AD, same prefix."},
 {obj:"3.3",c:"static",q:"show ip route static",a:"#show ip route static\nLists only the S and S* routes currently installed",s:"show ip route static",
  x:"show ip route static filters the routing table to installed static routes, which is the quickest way to confirm that an ip route command took effect. A configured static that is missing here is either unresolvable (next hop or interface down) or losing on AD, as a floating static does while the primary is up. Compare with show running-config | include ip route, which shows configured routes whether installed or not.",
  w:"Configured but not in show ip route static = not usable or losing on AD."},
 {obj:"3.3",c:"static",q:"show ipv6 route",a:"#show ipv6 route [static]\nCodes C, L (/128), S, O; [AD/metric] like IPv4",s:"show ipv6 route",
  x:"show ipv6 route is the IPv6 routing table, with the same structure as IPv4: a code (C connected, L local /128, S static, O OSPFv3 and so on), the prefix, [AD/metric], and the next hop and interface on a second line. Adding 'static' filters to configured static routes. If the table is almost empty despite routes in the config, check that ipv6 unicast-routing is enabled and the interfaces are up.",
  w:"Same codes and brackets as IPv4, prefixes in /len."},

 /* ---------- ospf (40) — 3.4 single-area OSPFv2 ---------- */
 {obj:"3.4",c:"ospf",q:"OSPF — protocol type",a:"#Link-state IGP, open standard, AD 110\nEvery router in the area holds the same LSDB and runs SPF (Dijkstra)",s:"Open-standard link-state IGP",
  x:"OSPF routers flood link-state advertisements describing their links so that every router in an area builds an identical link-state database, then each one runs the SPF (Dijkstra) algorithm to compute its own shortest-path tree. This differs from distance-vector protocols like RIP, which only pass along best routes. OSPF is an open standard, runs directly over IP as protocol 89, uses AD 110 and a cost metric based on bandwidth.",
  w:"Link-state: share the map, each router computes its own paths."},
 {obj:"3.4",c:"ospf",q:"LSA type 1 vs type 2",a:"#Type 1 Router LSA: every router, its own links\nType 2 Network LSA: made by the DR for a multi-access segment",s:"Router LSA from each router; network LSA from the DR",
  x:"In a single area the database is built mainly from two LSA types. Every OSPF router originates one type 1 (router) LSA listing its links and costs within the area. On a broadcast segment with a DR, the DR originates a type 2 (network) LSA that lists all routers attached to that segment, so the segment is modeled as one node. Point-to-point links produce no type 2 LSA because they elect no DR.",
  w:"Type 1 = each router. Type 2 = the DR, per segment."},
 {obj:"3.4",c:"ospf",q:"Why OSPF uses areas — and area 0",a:"#Areas limit LSA flooding and SPF work\nArea 0 is the backbone; CCNA configures a single area, area 0",s:"Areas contain flooding; area 0 is the backbone",
  x:"Dividing OSPF into areas keeps detailed LSAs inside each area, so SPF runs on smaller databases and changes in one area cause less churn elsewhere. Any multi-area design must have a backbone, area 0, that all other areas connect to through ABRs. CCNA v1.1 asks you to configure and verify single-area OSPFv2, which by convention is area 0; every interface you enable must agree on the area number with its neighbor.",
  w:"Single area = area 0 everywhere."},
 {obj:"3.4",c:"ospf",q:"router ospf 1 — the process ID",a:"#Locally significant number, 1–65535\nNeighbors do not need matching process IDs",s:"Local process number; need not match neighbors",
  x:"The number in router ospf 1 only identifies the OSPF process on that router; it is never sent in hello packets, so R1 running process 1 forms adjacencies with R2 running process 10 without any problem. This is a favourite exam trap because it looks like an AS number. What must match between neighbors is the area, subnet, timers, authentication and the stub flag, not the process ID.",
  w:"Process ID is local; area must match."},
 {obj:"3.4",c:"ospf",q:"network command in OSPF",a:"#network 10.0.12.0 0.0.0.3 area 0\nEnables OSPF on interfaces whose IP falls in the range",s:"network address wildcard area N",
  x:"Under router ospf, the network command uses an address and a wildcard mask to select interfaces: any interface whose primary IP matches the range is enabled for OSPF in the named area, starts sending hellos and has its connected subnet advertised. The mask and the advertised prefix are taken from the interface itself, not from the command. 'network 10.0.12.1 0.0.0.0 area 0' matches only the interface with exactly that address.",
  w:"network = 'which interfaces', not 'which route'."},
 {obj:"3.4",c:"ospf",q:"Wildcard mask in OSPF network statements",a:"#0 bits must match, 1 bits are ignored\n0.0.0.255 matches a /24; 0.0.0.0 matches one exact IP",s:"Zero bits must match; one bits are don't-care",
  x:"OSPF network statements use wildcard masks, the bitwise inverse of a subnet mask: 255.255.255.252 becomes 0.0.0.3. A quick rule is 255.255.255.255 minus the subnet mask. 'network 0.0.0.0 255.255.255.255 area 0' matches every interface. Typing a subnet mask by mistake (network 10.0.12.0 255.255.255.0 area 0) still parses, but it matches far more interfaces than intended, which is a common lab error.",
  w:"Wildcard = 255.255.255.255 minus the mask."},
 {obj:"3.4",c:"ospf",q:"Interface method: ip ospf 1 area 0",a:"#interface g0/0 → ip ospf 1 area 0\nEnables OSPF directly on that interface, no network command",s:"ip ospf process area under the interface",
  x:"Instead of network statements, OSPFv2 can be enabled per interface with ip ospf process-id area area-id in interface configuration. It is explicit and avoids wildcard mistakes, and if both methods cover an interface the interface command takes precedence. show ip ospf interface and show ip protocols reflect it ('Interfaces Configured Explicitly'). OSPFv3 for IPv6 is configured only this way.",
  w:"Per-interface OSPF: no wildcards to get wrong."},
 {obj:"3.4",c:"ospf",q:"passive-interface",a:"#passive-interface g0/1 (under router ospf)\nAdvertises the subnet but sends no hellos and forms no neighbors",s:"Advertise the subnet, send no hellos there",
  x:"A passive interface is still part of OSPF, so its connected subnet is included in the router LSA, but the router stops sending and processing hellos on it. Use it on LAN interfaces facing only end hosts: it removes needless OSPF traffic and prevents a rogue device from forming an adjacency. passive-interface default makes every interface passive, after which you re-enable the uplinks with no passive-interface.",
  w:"Passive = advertised, but silent."},
 {obj:"3.4.d",c:"ospf",q:"OSPF router ID — selection order",a:"#1 router-id command · 2 highest loopback IP · 3 highest active interface IP\nChosen once when the process starts",s:"Manual, then highest loopback, then highest interface",
  x:"The router ID is a 32-bit value written like an IPv4 address that names the router in every LSA. IOS picks it in this order: the router-id command under router ospf; otherwise the highest IP on an up loopback; otherwise the highest IP on any other up interface. The interfaces need not be running OSPF. Setting it manually is best practice because it never changes unexpectedly.",
  w:"Manual > loopback > physical."},
 {obj:"3.4.d",c:"ospf",q:"Changing the router ID",a:"#router-id 1.1.1.1, then clear ip ospf process\nA new RID only takes effect when the process restarts",s:"Set router-id, then clear ip ospf process",
  x:"The router ID is locked in when the OSPF process starts. If you enter or change router-id later, IOS warns that the new value takes effect after reload or after clear ip ospf process. Clearing the process tears down and rebuilds every adjacency, so it is disruptive. Adding a new loopback with a higher address likewise does nothing until the process restarts.",
  w:"New RID? clear ip ospf process (or reload)."},
 {obj:"3.4.d",c:"ospf",q:"Duplicate OSPF router IDs",a:"#Neighbors will not form or the LSDB breaks\nIOS logs a duplicate router-id message",s:"Adjacency fails; RIDs must be unique",
  x:"Each OSPF router must have a unique router ID because LSAs are keyed by it. Two directly connected routers with the same RID will not become neighbors, and IOS logs a duplicate router-id warning. Duplicates elsewhere in the area cause LSAs to overwrite one another and routes to flap. This often happens when configurations are copied between routers including the router-id line.",
  w:"Copy-paste configs: change the router-id."},
 {obj:"3.4.d",c:"ospf",q:"Why use a loopback for the OSPF RID?",a:"#A loopback never goes down unless shut\nSo the RID is stable and reachable on any working path",s:"Loopbacks stay up, giving a stable RID",
  x:"Loopback interfaces are virtual and stay up/up as long as the router runs, so a router ID taken from a loopback does not depend on any physical link. That is why IOS prefers the highest loopback over physical interfaces when no router-id command exists. Many designs set router-id equal to a loopback address so the RID is both stable and pingable for troubleshooting.",
  w:"Loopback = always up = stable RID."},
 {obj:"3.4.a",c:"ospf",q:"Hello and dead timers — broadcast defaults",a:"#Hello 10 s, dead 40 s\nOn broadcast and point-to-point networks; must match neighbors",s:"Hello 10 seconds, dead 40 seconds",
  x:"OSPF routers send hellos every 10 seconds on broadcast (Ethernet) and point-to-point networks and declare a neighbor down if no hello arrives within the dead interval, 40 seconds by default (four hellos). Both values are carried in the hello and must match for an adjacency to form. Change them with ip ospf hello-interval and ip ospf dead-interval on the interface; show ip ospf interface displays them.",
  w:"10/40, and they must match."},
 {obj:"3.4.a",c:"ospf",q:"Requirements for an OSPF adjacency",a:"#Same area, subnet/mask, hello/dead, authentication, stub flag\nPlus unique RIDs, matching MTU, interfaces not passive",s:"Area, subnet, timers, auth, stub flag must match",
  x:"Two OSPF routers on a link become neighbors only if their hellos agree on area ID, subnet and mask, hello and dead intervals, authentication settings and the area type (stub flag). Their router IDs must differ and neither interface can be passive. A mismatched MTU does not stop the hellos but stalls the adjacency at EXSTART/EXCHANGE. Process ID and interface cost do not have to match.",
  w:"Process ID and cost can differ; area, subnet, timers cannot."},
 {obj:"3.4.a",c:"ospf",q:"MTU mismatch symptom",a:"#Neighbor stuck in EXSTART or EXCHANGE\nHellos work, but DBD packets are rejected",s:"Adjacency stuck in EXSTART or EXCHANGE",
  x:"Interface MTU is not checked in hellos, so routers with different MTUs reach 2-WAY normally. The MTU is carried in database description packets, and a router rejects DBDs advertising a larger MTU than its own, so the pair loops in EXSTART or EXCHANGE and never reaches FULL. Fix it by matching the MTU (or, less cleanly, ip ospf mtu-ignore). This is the classic explanation for that stuck state.",
  w:"Stuck in EXSTART/EXCHANGE = suspect MTU."},
 {obj:"3.4.a",c:"ospf",q:"Area or subnet mismatch symptom",a:"#No neighbor at all\nHellos are discarded, so show ip ospf neighbor is empty",s:"No adjacency; neighbor never appears",
  x:"If two routers disagree on area, subnet mask, hello/dead timers, authentication or stub flag, each discards the other's hellos, so the neighbor never even reaches INIT and is missing from show ip ospf neighbor. IOS may log a mismatch message (for example 'mismatched area ID'). Compare show ip ospf interface on both sides to find the difference. Contrast this with MTU problems, which let the neighbor appear but stall it.",
  w:"Hello mismatch = no neighbor listed."},
 {obj:"3.4.a",c:"ospf",q:"OSPF neighbor states in order",a:"#Down → Init → 2-Way → ExStart → Exchange → Loading → Full\n(Attempt exists only on NBMA)",s:"Down, Init, 2-Way, ExStart, Exchange, Loading, Full",
  x:"Neighbors move from Down to Init when a hello arrives, to 2-Way when a router sees its own RID listed in the neighbor's hello, then through ExStart (choose who leads the exchange), Exchange (trade DBD summaries), Loading (request and receive missing LSAs) and finally Full, where their databases are synchronised. DR/BDR election happens at the 2-Way stage on broadcast segments.",
  w:"Down, Init, 2-Way, ExStart, Exchange, Loading, Full."},
 {obj:"3.4.a",c:"ospf",q:"INIT state",a:"#Hello received, but my RID is not in it yet\nOne-way communication",s:"Hello seen, own RID not yet in neighbor's list",
  x:"INIT means a router has received a hello from a neighbor but its own router ID does not yet appear in that hello's neighbor list, so communication is one-way. Normally this lasts at most one hello interval. A neighbor stuck in INIT points to a one-way problem: an ACL dropping inbound OSPF multicast, a unidirectional link, or authentication misconfigured on one side.",
  w:"Stuck in INIT = they cannot hear me."},
 {obj:"3.4.a",c:"ospf",q:"2-WAY state",a:"#Each router sees its RID in the other's hello\nBidirectional; DR/BDR election happens here",s:"Bidirectional hellos confirmed",
  x:"Reaching 2-WAY means bidirectional communication is confirmed. On point-to-point links routers then move on to form a full adjacency. On broadcast segments the DR and BDR are elected at this point, and only the DR and BDR go on to FULL with everyone; two DROTHERs stay in 2-WAY with each other. So 2-WAY is a final state for some pairs, not necessarily a fault.",
  w:"2-WAY: we hear each other; DROTHERs stop here."},
 {obj:"3.4.a",c:"ospf",q:"EXSTART and EXCHANGE",a:"#ExStart: elect master/slave by higher RID\nExchange: swap DBD summaries of each LSDB",s:"Master/slave election, then DBD summaries",
  x:"In EXSTART the two routers decide which will be master for the database exchange; the higher router ID becomes master and controls the DBD sequence numbers. In EXCHANGE they send database description packets that list LSA headers (not full LSAs) so each can see what it is missing. MTU is carried here, which is why an MTU mismatch stalls in these two states.",
  w:"ExStart picks a leader; Exchange swaps tables of contents."},
 {obj:"3.4.a",c:"ospf",q:"LOADING and FULL",a:"#Loading: request missing LSAs (LSR → LSU → LSAck)\nFull: databases are identical",s:"Request missing LSAs, then databases synchronised",
  x:"In LOADING a router sends link-state requests for LSAs it saw in the DBDs but does not have, receives them in link-state updates and acknowledges them. When nothing is outstanding, the pair reaches FULL: their databases are synchronised and SPF can use the link. FULL is the normal end state on point-to-point links and between any router and the DR or BDR.",
  w:"FULL = synchronised."},
 {obj:"3.4.c",c:"ospf",q:"2WAY/DROTHER in show ip ospf neighbor — fault or normal?",a:"#Normal on a broadcast segment\nTwo non-DR, non-BDR routers do not go Full with each other",s:"Normal between two non-DR routers",
  x:"On an Ethernet segment with several OSPF routers, every router forms a FULL adjacency with the DR and the BDR only. Two routers that are neither (DROTHERs) see each other as 2WAY/DROTHER and stop there, which keeps the number of adjacencies and flooded LSAs down. An exam exhibit showing FULL/DR, FULL/BDR and 2WAY/DROTHER entries on one LAN is healthy and should not be read as a fault.",
  w:"2WAY/DROTHER on a LAN = healthy."},
 {obj:"3.4.c",c:"ospf",q:"Why elect a DR and BDR?",a:"#Reduce adjacencies and flooding on multi-access links\nEveryone goes Full with the DR/BDR only",s:"Cut adjacencies and LSA flooding on a LAN",
  x:"Without a DR, n routers on one Ethernet segment would need n(n-1)/2 full adjacencies and each change would be flooded many times. With a DR, routers send updates to the DR (and BDR), which redistributes them to all, and the DR represents the segment with a type 2 network LSA. The BDR keeps a full copy so it can take over immediately if the DR fails.",
  w:"DR = the segment's hub for LSAs; BDR = hot spare."},
 {obj:"3.4.c",c:"ospf",q:"DR/BDR election rules",a:"#Highest interface priority, then highest router ID\nDefault priority 1; priority 0 never becomes DR/BDR",s:"Highest priority, then highest RID",
  x:"On each broadcast segment the router with the highest OSPF interface priority becomes DR and the next highest becomes BDR; a tie is broken by the highest router ID, not the highest interface IP. The default priority is 1 and the range is 0–255. Priority 0 removes a router from the election entirely, so it will always be DROTHER. Elections are per segment, so one router can be DR on one LAN and DROTHER on another.",
  w:"Priority first, RID breaks ties, 0 opts out."},
 {obj:"3.4.c",c:"ospf",q:"Is DR election preemptive?",a:"#No — an existing DR keeps the role\nA better router joining later does not take over",s:"No; the current DR stays until it fails",
  x:"OSPF DR election is non-preemptive. Once a DR and BDR exist, a newly arriving router with a higher priority or RID becomes a DROTHER. If the DR fails, the BDR is promoted and a new BDR is elected. To force a particular router to become DR you set the priorities and then reset the adjacencies (for example with clear ip ospf process on the current DR), which is a common lab task.",
  w:"Non-preemptive: higher priority must wait its turn."},
 {obj:"3.4.c",c:"ospf",q:"ip ospf priority",a:"#ip ospf priority 0–255 (interface command)\n255 favours DR; 0 = never DR or BDR",s:"ip ospf priority value under the interface",
  x:"ip ospf priority is configured per interface because the election happens per segment. Setting 255 on the router you want as DR and 0 on routers that should never hold the role (such as small branch routers on a shared segment) gives a predictable result. The new value only influences the next election, which, because election is non-preemptive, may need an adjacency reset to run.",
  w:"Priority is per interface, per segment."},
 {obj:"3.4.c",c:"ospf",q:"OSPF multicast addresses",a:"#224.0.0.5 = AllSPFRouters · 224.0.0.6 = AllDRouters\nDROTHERs send updates to .6; the DR floods to .5",s:"224.0.0.5 all OSPF routers; 224.0.0.6 DR/BDR",
  x:"Hellos go to 224.0.0.5, which every OSPF router listens to. On a broadcast segment, a DROTHER that needs to report a change sends its link-state update to 224.0.0.6, which only the DR and BDR listen to; the DR then floods it to 224.0.0.5 so everyone receives it. Both addresses are link-local multicast and never routed. ACLs that block them will break OSPF on that interface.",
  w:".5 = everyone, .6 = DR and BDR only."},
 {obj:"3.4.b",c:"ospf",q:"OSPF point-to-point network type",a:"#No DR/BDR election; neighbors go straight to Full\nDefault on serial (HDLC/PPP); hello 10, dead 40",s:"No DR election; routers go straight to Full",
  x:"On a point-to-point network type there are only two routers, so no DR or BDR is needed: once hellos are bidirectional, the pair moves directly through ExStart to Full, and show ip ospf neighbor shows FULL/ with a dash instead of a DR role. Serial links with HDLC or PPP use this type by default. Hello and dead remain 10 and 40 seconds. No type 2 network LSA is created for the link.",
  w:"Point-to-point: FULL/ - , no DR."},
 {obj:"3.4.b",c:"ospf",q:"ip ospf network point-to-point",a:"#Make an Ethernet link behave as point-to-point\nSkips DR election and speeds up adjacency",s:"Changes an Ethernet link to point-to-point type",
  x:"Ethernet interfaces default to the broadcast network type, so even a router-to-router /30 elects a DR and BDR and waits for the election before converging. Configuring ip ospf network point-to-point on both ends removes the election and the type 2 LSA, giving faster adjacencies and a simpler database. Both sides should use the same type; mixing broadcast and point-to-point leads to adjacency or route problems.",
  w:"Router-to-router Ethernet? Make it point-to-point on both ends."},
 {obj:"3.4.b",c:"ospf",q:"Broadcast vs point-to-point: default by interface",a:"#Ethernet = broadcast (DR/BDR)\nSerial HDLC/PPP = point-to-point (no DR)",s:"Ethernet broadcast, serial point-to-point",
  x:"IOS picks the OSPF network type from the interface: Ethernet (including GigabitEthernet and router subinterfaces) is broadcast, which elects a DR and BDR and shows roles like FULL/DR; serial interfaces running HDLC or PPP are point-to-point, which elects none and shows FULL/ -. show ip ospf interface reports 'Network Type BROADCAST' or 'POINT_TO_POINT'. Both default types use a 10-second hello.",
  w:"Check 'Network Type' in show ip ospf interface."},
 {obj:"3.4",c:"ospf",q:"OSPF cost formula",a:"#Cost = reference bandwidth ÷ interface bandwidth\nDefault reference 100 Mbps; minimum cost 1",s:"Reference bandwidth divided by interface bandwidth",
  x:"Each OSPF interface has a cost; a route's metric is the sum of the outgoing interface costs along the path to the destination. By default IOS divides a 100 Mbps reference bandwidth by the interface bandwidth and rounds down, with a floor of 1. So a 10 Mbps Ethernet costs 10, FastEthernet 1 and a 1.544 Mbps T1 64. The interface bandwidth value used is the configured bandwidth setting, not a measured speed.",
  w:"100 Mbps ÷ bandwidth, never below 1."},
 {obj:"3.4",c:"ospf",q:"Default OSPF cost of Fa, Gi and 10G",a:"#All cost 1\nAnything 100 Mbps or faster rounds to the minimum",s:"FastEthernet, Gigabit and 10G all cost 1",
  x:"With the default 100 Mbps reference, FastEthernet (100/100), GigabitEthernet (100/1000 = 0.1) and 10 Gigabit (0.01) all end up at cost 1, so OSPF cannot prefer a gigabit path over a FastEthernet path. That is why designs raise the reference bandwidth or set costs manually. Exam items that ask for a path cost over mixed Fa and Gi links usually rely on every hop being 1.",
  w:"Default OSPF can't tell Fa from Gi."},
 {obj:"3.4",c:"ospf",q:"auto-cost reference-bandwidth",a:"#auto-cost reference-bandwidth 10000 (in Mbps, under router ospf)\nSet the same value on every router in the area",s:"Raise the reference bandwidth in router ospf",
  x:"auto-cost reference-bandwidth changes the numerator of the cost formula, entered in Mbps. With 10000 (10 Gbps), Gigabit costs 10, FastEthernet 100 and 10 Gigabit 1, so faster links finally win. Every router in the area should use the same value; otherwise routers calculate inconsistent costs and paths can be suboptimal. IOS prints a reminder to keep it consistent when you change it.",
  w:"Reference bandwidth is in Mbps and should match area-wide."},
 {obj:"3.4",c:"ospf",q:"ip ospf cost",a:"#ip ospf cost 50 (interface command)\nOverrides the bandwidth-based calculation on that interface",s:"Set an interface's OSPF cost directly",
  x:"ip ospf cost sets a fixed cost on one interface, overriding both the reference bandwidth and the bandwidth command. It is the most direct way to steer traffic onto a preferred link. Cost is applied in the outbound direction, so to change which path R1 uses toward a network you adjust costs on R1's (and downstream routers') outgoing interfaces. Changing the bandwidth command also changes cost but can affect other features.",
  w:"ip ospf cost wins over any calculation."},
 {obj:"3.4",c:"ospf",q:"Calculating an OSPF route metric",a:"#Sum the outgoing interface costs to the destination\nIncluding the destination LAN interface on the last router",s:"Add outgoing costs along the path, including the LAN",
  x:"An OSPF route's metric is the total cost of every outgoing interface from this router to the destination, including the far router's interface onto the destination subnet. From R1 over two Gigabit links (cost 1 each, default reference) to a FastEthernet LAN (cost 1), the metric is 3. Inbound interface costs are not counted. The result shows as the second number in the route, such as [110/3].",
  w:"Count outgoing interfaces only, LAN included."},
 {obj:"3.4",c:"ospf",q:"default-information originate",a:"#Advertise this router's default route into OSPF\nNeighbors learn O*E2 0.0.0.0/0",s:"Advertises the local default route into OSPF",
  x:"Configured under router ospf on the edge router, default-information originate advertises a default route into OSPF as an external type 5 LSA so every other router learns O*E2 0.0.0.0/0 and sets its gateway of last resort. By default it only does this if the edge router itself has a default route in its table (usually a static toward the ISP). Adding 'always' advertises it regardless.",
  w:"Needs a local default first — unless you add 'always'."},
 {obj:"3.4.a",c:"ospf",q:"show ip ospf neighbor",a:"#show ip ospf neighbor\nNeighbor ID (RID), Pri, State/role, Dead Time, Address, Interface",s:"show ip ospf neighbor",
  x:"show ip ospf neighbor lists each neighbor by router ID with its priority, state and DR role (FULL/DR, FULL/BDR, 2WAY/DROTHER, FULL/ -), the time left on its dead timer, the neighbor's interface IP and the local interface. It is the first check for adjacency problems. Note that the Neighbor ID is the RID, which may differ from the Address column, the IP on the shared link.",
  w:"Neighbor ID = RID; Address = link IP."},
 {obj:"3.4",c:"ospf",q:"show ip ospf interface",a:"#show ip ospf interface [g0/0]\nArea, cost, network type, priority, DR/BDR, hello/dead, neighbor count",s:"show ip ospf interface",
  x:"show ip ospf interface gives per-interface OSPF detail: IP and area, process ID and router ID, network type, cost, state (DR, BDR, DROTHER, P2P), priority, the DR and BDR IDs, hello/dead/wait timers, whether the interface is passive ('No Hellos'), and neighbor and adjacency counts. It is the command to compare between two routers when they fail to become neighbors.",
  w:"Neighbors won't form? Compare show ip ospf interface on both."},
 {obj:"3.4",c:"ospf",q:"show ip ospf interface brief",a:"#show ip ospf interface brief\nOne line per OSPF interface: PID, area, IP/mask, cost, state, Nbrs F/C",s:"show ip ospf interface brief",
  x:"The brief form lists each OSPF-enabled interface on one line with process ID, area, address and mask, cost, state (DR, BDR, DROTHER, P2P, or LOOP for loopbacks) and neighbor counts as Full/Count. It quickly answers which interfaces are in OSPF, in which area, and at what cost. A missing interface usually means the network statement or ip ospf command did not match it.",
  w:"Is the interface even in OSPF? Check the brief."},
 {obj:"3.4",c:"ospf",q:"show ip ospf database",a:"#show ip ospf database\nThe LSDB: Router (type 1) and Net (type 2) Link States",s:"show ip ospf database",
  x:"show ip ospf database displays the link-state database, grouped by LSA type: 'Router Link States' (type 1, one per router, by RID) and 'Net Link States' (type 2, one per DR segment, keyed by the DR's interface IP), plus summary and external sections when present. In a healthy single area, every router shows the same database. It is useful for confirming that a router's LSA is reaching others.",
  w:"Same area = same database on every router."},
 {obj:"3.4",c:"ospf",q:"show ip protocols (OSPF)",a:"#show ip protocols\nRouter ID, network statements, passive interfaces, reference bandwidth, sources",s:"show ip protocols",
  x:"show ip protocols summarises each routing process: for OSPF it shows the process ID and router ID, the networks being routed (network statements or explicitly configured interfaces), passive interfaces, the reference bandwidth, the maximum paths, routing information sources with their AD and last update, and the administrative distance. It is the quickest way to check a router's OSPF configuration without reading the running config.",
  w:"Config summary for every routing protocol in one command."},

 /* ---------- fhrp (22) — 3.5 first hop redundancy protocols ---------- */
 {obj:"3.5",c:"fhrp",q:"Why first hop redundancy is needed",a:"#Hosts have one default gateway — a single point of failure\nAn FHRP lets two routers share one virtual gateway IP",s:"Remove the default gateway as a single point of failure",
  x:"End hosts are configured (statically or by DHCP) with a single default gateway address. If the router owning that address fails, hosts cannot leave their subnet even though another router is on the same LAN. A first hop redundancy protocol lets two or more routers present one virtual IP and virtual MAC, so a backup router takes over the gateway role without any change on the hosts.",
  w:"FHRP: hosts keep one gateway address, routers share it."},
 {obj:"3.5",c:"fhrp",q:"Virtual IP and virtual MAC",a:"#Hosts use the virtual IP as their gateway\nARP for it returns the virtual MAC, owned by the active router",s:"Shared gateway IP that resolves to a virtual MAC",
  x:"Each FHRP group has a virtual IP address that hosts use as their default gateway and a virtual MAC address that the active (or master) router answers ARP with. On failover, the new active router starts using the same virtual MAC and sends gratuitous ARP so switches update their MAC tables. Hosts never need to re-ARP or change settings, which is what makes the failover transparent.",
  w:"Same IP, same MAC, different router behind it."},
 {obj:"3.5",c:"fhrp",q:"HSRP",a:"#Hot Standby Router Protocol — Cisco proprietary\nOne active router forwards; one standby waits",s:"Cisco-proprietary active/standby gateway protocol",
  x:"HSRP is Cisco's FHRP. Routers in a group elect one active router that answers for the virtual IP and MAC and forwards host traffic, and one standby router that monitors it and takes over if hellos stop. Other group members are listen-state. Only the active router forwards for a group, so load sharing needs multiple groups (for example, one per VLAN with different active routers).",
  w:"HSRP: active + standby, Cisco only."},
 {obj:"3.5",c:"fhrp",q:"HSRP active router election",a:"#Highest priority wins; tie → highest interface IP\nDefault priority 100, range 0–255",s:"Highest priority, then highest interface IP",
  x:"HSRP elects the active router by priority, default 100, highest wins. If priorities tie, the router with the highest IP address on the HSRP interface becomes active. The next best becomes standby. Note the difference from OSPF DR election, whose tie-breaker is router ID. Priority is set with standby group priority value on the interface.",
  w:"HSRP tie-breaker = highest interface IP."},
 {obj:"3.5",c:"fhrp",q:"HSRP preemption",a:"#Off by default\nWithout standby preempt, a higher-priority router will not take over",s:"Disabled by default in HSRP",
  x:"With HSRP's default settings, if the active router fails and later recovers, it stays in standby even if its priority is higher, because preemption is disabled. Configuring standby group preempt lets a router with higher priority reclaim the active role. A common exam scenario shows a primary router with priority 110 that is still standby after a reboot; the missing piece is preempt.",
  w:"HSRP won't take back the role unless you say preempt."},
 {obj:"3.5",c:"fhrp",q:"HSRP hello and hold timers",a:"#Hello 3 s, hold 10 s\nStandby takes over after 10 s without hellos",s:"Hello 3 seconds, hold 10 seconds",
  x:"HSRP routers exchange hellos every 3 seconds by default; if the standby router hears nothing from the active for the 10-second hold time, it becomes active. The timers can be tuned with standby group timers, including sub-second values for faster failover. Compare OSPF's 10/40 on broadcast networks; the two sets of numbers are easy to mix up on the exam.",
  w:"HSRP 3/10, OSPF 10/40."},
 {obj:"3.5",c:"fhrp",q:"HSRP version 1 vs version 2",a:"#v1: groups 0–255, 224.0.0.2, MAC 0000.0C07.ACxx\nv2: groups 0–4095, 224.0.0.102, MAC 0000.0C9F.Fxxx; supports IPv6",s:"v1 groups 0–255; v2 groups 0–4095 and IPv6",
  x:"HSRPv1 is the default on IOS. It supports group numbers 0–255, sends hellos to 224.0.0.2 and uses virtual MAC 0000.0C07.ACxx where xx is the group in hex. HSRPv2, enabled with standby version 2, extends groups to 0–4095, sends to 224.0.0.102, uses 0000.0C9F.Fxxx (three hex digits of group), and adds IPv6 support. Both routers in a group must run the same version.",
  w:"v1 .2 + 07.AC; v2 .102 + 9F.F."},
 {obj:"3.5",c:"fhrp",q:"HSRPv1 MAC for group 10",a:"#0000.0C07.AC0A\nLast byte = group number in hex (10 = 0A)",s:"0000.0C07.AC0A",
  x:"The HSRPv1 virtual MAC is the fixed prefix 0000.0C07.AC followed by one byte holding the group number in hexadecimal. Group 1 is 0000.0C07.AC01, group 10 is 0000.0C07.AC0A and group 255 is 0000.0C07.ACFF. Seeing this MAC in an ARP table or exhibit identifies HSRPv1 and its group immediately. For HSRPv2, group 10 would be 0000.0C9F.F00A.",
  w:"Convert the group to hex and append it."},
 {obj:"3.5",c:"fhrp",q:"HSRP multicast addresses",a:"#v1 → 224.0.0.2 · v2 → 224.0.0.102\nUDP port 1985",s:"224.0.0.2 for v1, 224.0.0.102 for v2",
  x:"HSRPv1 sends hellos to 224.0.0.2, the all-routers link-local group, while HSRPv2 uses its own address, 224.0.0.102. Both use UDP port 1985. Matching an address to a protocol is a common recall item: 224.0.0.5/6 are OSPF, 224.0.0.10 is EIGRP, 224.0.0.18 is VRRP, 224.0.0.102 is HSRPv2 (and GLBP uses 224.0.0.102 as well).",
  w:"HSRP v1 .2, v2 .102; VRRP .18."},
 {obj:"3.5",c:"fhrp",q:"Basic HSRP configuration",a:"#standby 1 ip 192.168.10.1\nstandby 1 priority 110 · standby 1 preempt",s:"standby group ip virtual-IP",
  x:"HSRP is configured on the LAN-facing interface (often an SVI or router subinterface). standby 1 ip 192.168.10.1 joins group 1 and sets the virtual IP, which must be in the interface's subnet but different from both routers' real addresses. standby 1 priority 110 favours this router and standby 1 preempt lets it reclaim the active role. Hosts use 192.168.10.1 as their gateway.",
  w:"standby group ip / priority / preempt."},
 {obj:"3.5",c:"fhrp",q:"show standby brief",a:"#show standby brief\nInterface, group, priority, P (preempt), state, active, standby, virtual IP",s:"show standby brief",
  x:"show standby brief summarises HSRP: one line per group with the interface, group number, local priority, a P if preempt is on, the local state (Active, Standby, Listen, Init), the addresses of the active and standby routers ('local' for this router) and the virtual IP. show standby (without brief) adds the virtual MAC, timers and version. These are the main HSRP verification commands.",
  w:"show standby brief: who is active, who is standby."},
 {obj:"3.5",c:"fhrp",q:"Load sharing with HSRP",a:"#Use multiple groups with different active routers\nE.g. R1 active for VLAN 10, R2 active for VLAN 20",s:"Several groups, each with a different active router",
  x:"An HSRP group has only one active forwarder, so the standby router sits idle for that group. To use both routers, configure several groups, typically one per VLAN, and set priorities so R1 is active for some and R2 for others. Each router backs up the other. This per-group sharing is sometimes called multiple HSRP. GLBP, by contrast, load balances within a single group.",
  w:"HSRP shares load per group, not per host."},
 {obj:"3.5",c:"fhrp",q:"VRRP",a:"#Virtual Router Redundancy Protocol — open standard\nOne master forwards; backups wait",s:"Open-standard master/backup gateway protocol",
  x:"VRRP is the IETF standard FHRP, so it works between routers from different vendors. One router in the group is the master and forwards traffic for the virtual IP; the others are backups. Like HSRP it has a default priority of 100 and a single forwarder per group. Its terminology (master/backup, not active/standby) is the giveaway on exam questions comparing FHRPs.",
  w:"VRRP: standard, master/backup."},
 {obj:"3.5",c:"fhrp",q:"VRRP virtual MAC",a:"#0000.5E00.01xx\nxx = virtual router ID (group) in hex",s:"0000.5E00.01xx",
  x:"VRRP's virtual MAC for IPv4 is 0000.5E00.01 followed by the group number (virtual router ID) in hex, so group 10 is 0000.5E00.010A. The 00-00-5E prefix is the IANA block, reflecting VRRP's standards origin, in contrast to HSRP's Cisco 0000.0C prefix. VRRP advertisements go to multicast 224.0.0.18 using IP protocol 112.",
  w:"5E = IANA = VRRP; 0C = Cisco = HSRP."},
 {obj:"3.5",c:"fhrp",q:"VRRP preemption default",a:"#On by default\nA higher-priority backup takes over from the master automatically",s:"Enabled by default in VRRP",
  x:"VRRP enables preemption by default, so a router with higher priority that comes online will take over as master without extra configuration. HSRP is the opposite: preemption is off until you configure standby preempt. Which FHRP preempts by default is a favourite comparison item, alongside who is proprietary and what the roles are called.",
  w:"VRRP preempts by default; HSRP doesn't."},
 {obj:"3.5",c:"fhrp",q:"VRRP using a real interface address",a:"#Allowed: the virtual IP may be a router's own IP\nThat router (the owner) gets priority 255 and is master",s:"Virtual IP can equal the master's interface IP",
  x:"VRRP lets the virtual IP be the actual interface address of one of the routers. That router is the IP address owner, automatically takes priority 255 and is master whenever it is up. This lets you add redundancy to an existing gateway without changing hosts. HSRP does not allow this: its virtual IP must be a separate, unused address in the subnet.",
  w:"VRRP can reuse a real IP; HSRP needs a spare one."},
 {obj:"3.5",c:"fhrp",q:"GLBP",a:"#Gateway Load Balancing Protocol — Cisco proprietary\nLoad balances one virtual IP across several routers",s:"Cisco protocol that load balances one gateway IP",
  x:"GLBP provides redundancy and load balancing in a single group. All hosts use the same virtual IP, but when they ARP for it they receive different virtual MACs, each belonging to a different router, so traffic is spread across up to four forwarders. If one fails, another router adopts its MAC. Like HSRP it is Cisco proprietary; neither HSRP nor VRRP load balances within one group.",
  w:"GLBP = one IP, many MACs, many forwarders."},
 {obj:"3.5",c:"fhrp",q:"GLBP AVG and AVF roles",a:"#AVG answers ARP and hands out virtual MACs\nAVFs (up to 4) forward traffic for their assigned MAC",s:"AVG assigns MACs; AVFs forward",
  x:"In a GLBP group one router is the Active Virtual Gateway, elected by priority, which replies to ARP requests for the virtual IP and assigns each host one of the group's virtual MACs (round-robin by default). Up to four routers are Active Virtual Forwarders, each owning one virtual MAC and forwarding traffic sent to it. The AVG is usually also an AVF. A standby AVG takes over if the AVG fails.",
  w:"AVG = the dispatcher; AVF = the workers."},
 {obj:"3.5",c:"fhrp",q:"Which FHRP for a mixed-vendor network?",a:"#VRRP\nHSRP and GLBP are Cisco proprietary",s:"VRRP, the open standard",g:"fhrpwhich",
  x:"When gateway routers come from different vendors, only VRRP, an IETF standard, is guaranteed to interoperate. HSRP and GLBP run only on Cisco devices. If the question asks for load balancing within a single group among Cisco routers, choose GLBP; if it asks for the default Cisco FHRP, choose HSRP. Reading for 'vendor-neutral' or 'standards-based' points straight to VRRP.",
  w:"Mixed vendors = VRRP."},
 {obj:"3.5",c:"fhrp",q:"Which FHRP load balances within one group?",a:"#GLBP\nHSRP and VRRP have one forwarder per group",s:"GLBP, through multiple virtual MACs",g:"fhrpwhich",
  x:"Only GLBP spreads a single virtual IP's traffic across several active routers, because its AVG assigns different virtual MACs to different hosts. HSRP and VRRP each have exactly one forwarding router per group; you can approximate load sharing with them by creating several groups and splitting hosts or VLANs between them, but that requires more configuration and planning.",
  w:"Load balancing in one group = GLBP."},
 {obj:"3.5",c:"fhrp",q:"FHRP role names side by side",a:"#HSRP active/standby · VRRP master/backup · GLBP AVG/AVF\nOnly VRRP is an open standard",s:"Active/standby, master/backup, AVG/AVF",
  x:"Each FHRP names its roles differently, and exam items often use the role name as the only clue. HSRP has an active and a standby router; VRRP has a master and one or more backups; GLBP has one AVG plus up to four AVFs. HSRP and VRRP share a default priority of 100, but only VRRP preempts by default. Learn the trio of names as a set.",
  w:"Active = HSRP, master = VRRP, AVG = GLBP."},
 {obj:"3.5",c:"fhrp",q:"Gateway host setting with an FHRP",a:"#Hosts point to the virtual IP, never a router's real IP\nOtherwise failover does not protect them",s:"Configure hosts with the virtual IP only",
  x:"An FHRP only helps hosts whose default gateway is the group's virtual IP; the DHCP scope's default-router option should hand that address out. If hosts are configured with R1's real interface address instead, they lose connectivity when R1 fails even though HSRP fails over correctly. VRRP is the exception where the virtual IP may equal the owner's real address, by design.",
  w:"DHCP default-router = the virtual IP."},
];
